head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
//★Wcraft guide★ include부분 주석처리 -> include("/RexServer/rexscript/rexpert.js");
//★Wcraft guide★ include부분 주석처리 -> include("/RexServer/rexscript/rexpert_properties.js");
//★Wcraft guide★ include부분 주석처리 -> include("/RexServer/rexscript/rexpert_gauce.js");
scwin.vScrenID = "ULDSTF05601.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.mktTpCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //거래시장구분 1= 유가, 2=코스닥

scwin.fn_SetComboCode = function() {
    //주거래은행
    dts_MaintrBkCd.DataID = "/CodeAction.do?method=listInstCd&For=";
    dts_MaintrBkCd.Reset();
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_COM_NM.src = "../img/btn_search.gif";
        img_COM_NM.setDisabled(false);
    } else if (initTyp == "X") {
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
    }
};
scwin.fn_searchCode = function() {
    /*
    00685-명의개서대행기관
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='TRANSSTK_AGNT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetSecuId = function() {
    var vSecuId = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == SECUGRP_ID_IF) {
        vSecuId = SECUGRP_ID_MF; //SECUGRP_ID_IF 예비심사시 구분이 안됨.

    }
    return vSecuId;
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fn_GetSecuId();
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SEC; //신규등록시
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        txb_COM_ENG_NM.setValue(arrPar[0].COM_ENG_NM);
        dts_Item.setCellData(1, 'CNTR_ISO_CD', arrPar[0].CNTR_ISO_CD);
    }
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_read_sync = function() {
    dts_Item.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
    var url = "/Prelisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readPrelisting&inputMessageId=PREEXAM_INOUT";
    url += "&BZ_PROCS_NO=" + vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_changeForm(dts_Item.getCellData(1, "INVSTG_PROG_STAT_CD"));
    if (js_dep_cd == '2520' || //유가증권시장본부 - 상장부 - 상장심사팀
        js_dep_cd == '2540' ||
        js_dep_cd == '2615') {
        //기업심사팀(2615) by nhkw
        buttonSet.setUpdateStatus();
    } else {
        buttonSet.setErrorStatus(); //disable 시킨다.

    }
};
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = "02^심사완료,05^심사철회";
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = "02^심사완료,30^상장,05^심사철회";
scwin.fn_changeForm = function(gStatCd) {
    //alert("[gStatCd]:"+gStatCd);
    //alert("[gStatCd.charAt(0) ]:"+gStatCd.charAt(0) );
    if (gStatCd != "" && gStatCd.charAt(0) != '0') {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(true);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_2;
    } else {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_1;
    }
    cmb_INVSTG_PROG_STAT_CD.BindColVal = gStatCd;
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[법인]을 선택하세요.");
        img_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        $c.win.alert("[유가증권]을 선택하세요..");
        cmb_SECUGRP_ID.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[한글법인명]을 입력하세요..");
        txb_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_ENG_NM) == "") {
        $c.win.alert("[영문법인명]을 입력하세요..");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_ACPT_DD) == "") {
        $c.win.alert("[청구서접수일]을 입력하세요.");
        edt_INVSTG_BILL_ACPT_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "") {
        $c.win.alert("[심사상태]를 입력하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_LGSHRHD_NM) == "") {
        $c.win.alert("[최대주주]을 입력하세요.");
        txb_LGSHRHD_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LGSHRHD_RTO) == "") {
        $c.win.alert("[최대주주비율]을 입력하세요.");
        edt_LGSHRHD_RTO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CEO_NM) == "") {
        $c.win.alert("[대표이사]을 입력하세요.");
        txb_CEO_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_FOUND_DD) == "") {
        $c.win.alert("[설립일]을 입력하세요.");
        edt_FOUND_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_NM) == "") {
        $c.win.alert("[신청회사담당자명]을 입력하세요.");
        txb_APPL_COM_CHRG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_TEL_NO) == "") {
        $c.win.alert("[신청회사담당자연락처]를 입력하세요.");
        txb_APPL_COM_CHRG_TEL_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD1) == "") {
        $c.win.alert("[결산기_1]을 입력하세요.");
        edt_ACNTCLS_MMDD1.focus();
        return false;
    }
    if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD1)) return false;
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD2) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD2)) return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD3) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD3)) return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD4) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD4)) return false;
    }
    if ($c.stf.getObjectValue(cmb_TRANSSTK_AGNT_CD) == "") {
        $c.win.alert("[명의개서대행기관]을 선택하세요.");
        cmb_TRANSSTK_AGNT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_MAINTR_BK_CD) == "") {
        $c.win.alert("[주거래은행]을 선택하세요.");
        cmb_MAINTR_BK_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_STD_IND_CD) == "") {
        $c.win.alert("[업종]을 선택하세요.");
        txb_STD_IND_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ADDR) == "") {
        $c.win.alert("[본점소재지]을 입력하세요.");
        txb_ADDR.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_SHRS) == "") {
        $c.win.alert("[상장주식수]를 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_PARVAL) == "") {
        $c.win.alert("[액면가]를 입력하세요.");
        edt_PARVAL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_PUBOFR_SHRS) == "") {
        $c.win.alert("[공모주식수]를 입력하세요.");
        edt_PUBOFR_SHRS.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CAP) == "") {
        $c.win.alert("[자본금]을 입력하세요.");
        edt_CAP.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_PUBOFR_PRC) == "") {
        $c.win.alert("[공모가격]을 입력하세요.");
        edt_PUBOFR_PRC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) != "RT") {
        if ($c.stf.getObjectValue(edt_EXST_STRT_DD) == "") {
            $c.win.alert("[존립개시일]을 입력하세요.");
            edt_EXST_STRT_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_EXST_END_DD) == "") {
            $c.win.alert("[존립종료일]을 입력하세요.");
            edt_EXST_END_DD.focus();
            return false;
        }
    }
    if (parseInt(edt_EXST_STRT_DD.getValue(), 10) >= parseInt(edt_EXST_END_DD.getValue(), 10)) {
        $c.win.alert("[존립개시일]은 [존립종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    //alert(dts_Item.Text);
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_Item.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
            //alert("BZ_PROCS_NO>>>>>>>> :"+dts_Item.NameValue(1,"BZ_PROCS_NO"));
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_trs = function() {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    //alert("BZ_PROCS_NO <<<<<:"+dts_Item.NameValue(1,"BZ_PROCS_NO"));
    dts_Item.setCellData(1, "EXAMPRN_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "FST_EXAMPRN_EMP_NO", js_emp_no);
    trs_Save.Action = "/Prelisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveInvstPrelisting&inputMessageId=PREEXAM_INOUT";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};


/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 * 현업요청으로 기능삭제
 ***********************************************/
scwin.fn_print = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    //dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDSTF00002";
    var userParam = [{
        uid: "HEADER",
        unm: $c.stf.fn_getComboTextValue(cmb_SECUGRP_ID)
    }, {
        uid: "COM_NM",
        unm: dts_Item.getCellData(1, "COM_NM")
    }, {
        uid: "LGSHRHD_NM",
        unm: dts_Item.getCellData(1, "LGSHRHD_NM")
    }, {
        uid: "INVSTG_BILL_ACPT_DD",
        unm: dts_Item.getCellData(1, "INVSTG_BILL_ACPT_DD")
    }, {
        uid: "LGSHRHD_RTO",
        unm: dts_Item.getCellData(1, "LGSHRHD_RTO")
    }, {
        uid: "LIST_DD",
        unm: dts_Item.getCellData(1, "LIST_DD")
    }, {
        uid: "FST_EXAMPRN_EMP_NM",
        unm: dts_Item.getCellData(1, "FST_EXAMPRN_EMP_NM")
    }, {
        uid: "LIST_LM_CD",
        unm: $c.stf.fn_getComboTextValue(cmb_INVSTG_PROG_STAT_CD)
    }, {
        uid: "APPL_COM_CHRG_NM",
        unm: dts_Item.getCellData(1, "APPL_COM_CHRG_NM")
    }, {
        uid: "APPL_COM_CHRG_TEL_NO",
        unm: dts_Item.getCellData(1, "APPL_COM_CHRG_TEL_NO")
    }, {
        uid: "CEO_NM",
        unm: dts_Item.getCellData(1, "CEO_NM")
    }, {
        uid: "FOUND_DD",
        unm: dts_Item.getCellData(1, "FOUND_DD")
    }, {
        uid: "ACNTCLS_MM",
        unm: dts_Item.getCellData(1, "ACNTCLS_MMDD1") + "월"
    }, {
        uid: "EXST_STRT_DD",
        unm: dts_Item.getCellData(1, "EXST_STRT_DD") + dts_Item.getCellData(1, "EXST_END_DD")
    }, {
        uid: "MAINTR_BK_CD",
        unm: $c.stf.fn_getComboTextValue(cmb_MAINTR_BK_CD)
    }, {
        uid: "TRANSSTK_AGNT_CD",
        unm: dts_Item.getCellData(1, "TRANSSTK_AGNT_CD")
    }, {
        uid: "TRANSSTK_AGNT_CD",
        unm: $c.stf.fn_getComboTextValue(cmb_TRANSSTK_AGNT_CD)
    }, {
        uid: "ADDR",
        unm: dts_Item.getCellData(1, "ADDR")
    }, {
        uid: "STD_IND_NM",
        unm: dts_Item.getCellData(1, "STD_IND_NM")
    }, {
        uid: "LIST_SHRS",
        unm: dts_Item.getCellData(1, "LIST_SHRS")
    }, {
        uid: "TOT_ASST_AMT",
        unm: dts_Item.getCellData(1, "TOT_ASST_AMT")
    }, {
        uid: "PARVAL",
        unm: dts_Item.getCellData(1, "PARVAL")
    }, {
        uid: "TOT_CAP",
        unm: dts_Item.getCellData(1, "TOT_CAP")
    }, {
        uid: "CAP",
        unm: dts_Item.getCellData(1, "CAP")
    }, {
        uid: "PUBOFR_SHRS",
        unm: dts_Item.getCellData(1, "PUBOFR_SHRS")
    }, {
        uid: "PUBOFR_PRC",
        unm: dts_Item.getCellData(1, "PUBOFR_PRC")
    }];
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
