scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    if (vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('U');
        buttonSet.setUpdateStatus();
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_read_sync();
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    scwin.fn_SetComboCode();

    //alert( '[vBzProcsNo]'+vBzProcsNo);
    var parentWin = $c.frame.path("../");
    vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.mktTpCd = parentWin.scwin.mktTpCd;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    if (vBzProcsNo != "") {
        scwin.fn_read_sync();
        cmb_SECUGRP_ID.setDisabled(true);
    } else {
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PREEXAM_INOUT";
        dts_Item.reset();
        dts_Item.insertRow();
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID)); //부모창에서 증권그룹값이 가져온다.
        //alert( '[cmb_SECUGRP_ID]'+getObjectValue(cmb_SECUGRP_ID));
        scwin.fn_changeForm("02"); //초기값

    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "RT") {
        $c.stf.showObj(label_43, false);
    } else {
        $c.stf.showObj(label_43, true);
    }
};
